    <?php foreach($model['groups'] as $index=>$group): ?><section class="bot-config-group"><header><span><?= $escape(str_pad((string)($index+1),2,'0',STR_PAD_LEFT)) ?></span><div><h2><?= $escape($group['title']) ?></h2><p><?= $escape($group['description']) ?></p></div></header><div class="bot-fields">
