        <?php if($field['type']==='boolean'): ?><input type="hidden" name="cfg[<?= $escape($field['key']) ?>]" value="0"><label class="bot-toggle"><input id="<?= $escape($id) ?>" type="checkbox" name="cfg[<?= $escape($field['key']) ?>]" value="1"<?= $field['value']==='1'?' checked':'' ?>><span aria-hidden="true"></span><small><?= $field['value']==='1'?'Włączone':'Wyłączone' ?></small></label>
