        <?php elseif($field['type']==='topics'): ?><div class="bot-topics" data-bot-topics><?php foreach($field['topics'] as $i=>$topic): ?><div data-bot-topic><input type="hidden" name="topics[<?= $i ?>][key]" value="<?= $escape($topic['key']) ?>"><input aria-label="Nazwa tematu" type="text" name="topics[<?= $i ?>][label]" value="<?= $escape($topic['label']) ?>" maxlength="100" required><button type="button" data-bot-remove-topic aria-label="Usuń temat">×</button></div><?php endforeach ?><button type="button" class="bot-secondary" data-bot-add-topic>+ Dodaj temat</button></div>
