    <?php foreach($model['actions'] as $action): ?><form method="post" action="index.php?route=/admin/syntaxdev-bot" class="bot-action"><input type="hidden" name="_token" value="<?= $escape($model['token']) ?>"><input type="hidden" name="intent" value="bot_action"><input type="hidden" name="action" value="<?= $escape($action['action']) ?>"><input type="hidden" name="config_revision" value="<?= $escape($model['revision']) ?>"><input type="hidden" name="section" value="<?= $escape($model['section']) ?>"><input type="hidden" name="request_key" value="<?= $escape($action['request_key']) ?>"><p><?= $escape($action['description']) ?></p><?php if(!empty($model['unsaved'])): ?><div class="bot-notice is-error" role="alert">Zmiany nie są zapisane. Popraw formularz i zapisz konfigurację przed publikacją.</div><?php endif ?><button class="bot-primary" type="submit" data-bot-publish<?= !$model['ready']||!empty($model['unsaved'])?' disabled':'' ?>><?= $escape($action['label']) ?></button></form><?php endforeach ?>
